431	// DownloadCategory is a download directory category that files can be routed to by extension
432	type DownloadCategory struct {
433		Name       string   `json:"name"`                 // Name is the category display name, empty for built-in categories that use NameKey
434		Path       string   `json:"path"`                 // Path is the download directory of the category
435		NameKey    string   `json:"nameKey,omitempty"`    // NameKey is the i18n key of the built-in category name
436		IsBuiltIn  bool     `json:"isBuiltIn,omitempty"`  // IsBuiltIn marks the category as built-in
437		IsDeleted  bool     `json:"isDeleted,omitempty"`  // IsDeleted marks the built-in category as deleted
438		Extensions []string `json:"extensions,omitempty"` // Extensions is the file extension list routed to the category, without leading dots
439	}
440	
441	type DownloaderProxyConfig struct {
442		Enable bool `json:"enable"`
443		// System is the flag that use system proxy
444		System bool   `json:"system"`
445		Scheme string `json:"scheme"`
446		Host   string `json:"host"`
447		Usr    string `json:"usr"`
448		Pwd    string `json:"pwd"`
449	}
450	
451	func (cfg *DownloaderProxyConfig) ToHandler() func(r *http.Request) (*url.URL, error) {
452		if cfg == nil || cfg.Enable == false {
453			return nil
454		}
455		if cfg.System {
456			safeProxyReloadConf()
457			return ieproxy.GetProxyFunc()
458		}
459		if cfg.Scheme == "" || cfg.Host == "" {
460			return nil
461		}
462		return http.ProxyURL(util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd))
463	}
464	
465	// ToUrl returns the proxy url, just for git clone
466	func (cfg *DownloaderProxyConfig) ToUrl() *url.URL {
467		if cfg == nil || cfg.Enable == false {
468			return nil
469		}
470		if cfg.System {
471			safeProxyReloadConf()
472			static := ieproxy.GetConf().Static
473			if static.Active && len(static.Protocols) > 0 {
474				// If only one protocol, use it
475				if len(static.Protocols) == 1 {
476					for _, v := range static.Protocols {
477						return parseUrlSafe(v)
478					}
479				}
480				// Check https
481				if v, ok := static.Protocols["https"]; ok {
482					return parseUrlSafe(v)
483				}
484				// Check http
485				if v, ok := static.Protocols["http"]; ok {
486					return parseUrlSafe(v)
487				}
488			}
489			return nil
490		}
491		if cfg.Scheme == "" || cfg.Host == "" {
492			return nil
493		}
494		return util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd)
495	}
496	
497	var prcLock sync.Mutex
498	
499	func safeProxyReloadConf() {
500		prcLock.Lock()
501		defer prcLock.Unlock()
502	
503		ieproxy.ReloadConf()
504	}
505	
506	func parseUrlSafe(rawUrl string) *url.URL {
507		u, err := url.Parse(rawUrl)
508		if err != nil {
509			return nil
510		}
511		return u
512	}
