296	// MigrateLegacyExtraCategories moves the extra.downloadCategories list written
297	// by v2.0.0-beta builds into the top level categories field and clears the
298	// legacy key. The legacy list predates extension based routing, so built-in
299	// entries regain their default extension lists from their name key, while user
300	// created folders keep their empty list until edited in settings. It reports
301	// whether the config changed so the caller can persist the cleared key.
302	func (cfg *DownloaderStoreConfig) MigrateLegacyExtraCategories() bool {
303		if len(cfg.Categories) > 0 || cfg.Extra == nil {
304			return false
305		}
306		raw, ok := cfg.Extra["downloadCategories"]
307		if !ok {
308			return false
309		}
310		data, err := json.Marshal(raw)
311		if err != nil {
312			return false
313		}
314		var legacy []*DownloadCategory
315		if err := json.Unmarshal(data, &legacy); err != nil {
316			return false
317		}
318		categories := make([]*DownloadCategory, 0, len(legacy))
319		for _, category := range legacy {
320			if category == nil {
321				continue
322			}
323			if extensions, exist := builtinCategoryExtensions[category.NameKey]; exist && len(category.Extensions) == 0 {
324				category.Extensions = append([]string(nil), extensions...)
325			}
326			categories = append(categories, category)
327		}
328		if len(categories) == 0 {
329			return false
330		}
331		cfg.Categories = categories
332		delete(cfg.Extra, "downloadCategories")
333		return true
334	}
