336	// AutoCategorizeEnabled reports whether downloads are routed to category
337	// directories by file extension. The switch is optional: an unset value keeps
338	// the feature off, so an older config that never saved the field stays off.
339	func (cfg *DownloaderStoreConfig) AutoCategorizeEnabled() bool {
340		return cfg.AutoCategorize != nil && *cfg.AutoCategorize
341	}
