451	func (cfg *DownloaderProxyConfig) ToHandler() func(r *http.Request) (*url.URL, error) {
452		if cfg == nil || cfg.Enable == false {
453			return nil
454		}
455		if cfg.System {
456			safeProxyReloadConf()
457			return ieproxy.GetProxyFunc()
458		}
459		if cfg.Scheme == "" || cfg.Host == "" {
460			return nil
461		}
462		return http.ProxyURL(util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd))
463	}
464	
465	// ToUrl returns the proxy url, just for git clone
466	func (cfg *DownloaderProxyConfig) ToUrl() *url.URL {
467		if cfg == nil || cfg.Enable == false {
468			return nil
469		}
470		if cfg.System {
471			safeProxyReloadConf()
472			static := ieproxy.GetConf().Static
473			if static.Active && len(static.Protocols) > 0 {
474				// If only one protocol, use it
475				if len(static.Protocols) == 1 {
476					for _, v := range static.Protocols {
477						return parseUrlSafe(v)
478					}
479				}
480				// Check https
481				if v, ok := static.Protocols["https"]; ok {
482					return parseUrlSafe(v)
483				}
484				// Check http
485				if v, ok := static.Protocols["http"]; ok {
486					return parseUrlSafe(v)
487				}
488			}
489			return nil
490		}
491		if cfg.Scheme == "" || cfg.Host == "" {
492			return nil
493		}
494		return util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd)
495	}
496	
497	var prcLock sync.Mutex
498	
499	func safeProxyReloadConf() {
500		prcLock.Lock()
501		defer prcLock.Unlock()
502	
503		ieproxy.ReloadConf()
504	}
505	
506	func parseUrlSafe(rawUrl string) *url.URL {
507		u, err := url.Parse(rawUrl)
508		if err != nil {
509			return nil
510		}
511		return u
512	}
