200	func TestDownloaderStoreConfig_InitSeedsBuiltInCategories(t *testing.T) {
201		t.Run("fresh config with a download dir gets the built-in categories", func(t *testing.T) {
202			dir := t.TempDir()
203			cfg := &DownloaderStoreConfig{DownloadDir: dir}
204			cfg.Init()
205	
206			wantKeys := []string{"categoryMusic", "categoryVideo", "categoryDocument", "categoryProgram"}
207			wantNames := []string{"Music", "Video", "Document", "Program"}
208			if len(cfg.Categories) != len(wantKeys) {
209				t.Fatalf("categories = %d, want %d", len(cfg.Categories), len(wantKeys))
210			}
211			for i, category := range cfg.Categories {
212				if category.NameKey != wantKeys[i] {
213					t.Errorf("category[%d].NameKey = %q, want %q", i, category.NameKey, wantKeys[i])
214				}
215				if !category.IsBuiltIn {
216					t.Errorf("category[%d] %q is not built-in", i, category.NameKey)
217				}
218				if category.Path != filepath.Join(dir, wantNames[i]) {
219					t.Errorf("category[%d].Path = %q, want %q", i, category.Path, filepath.Join(dir, wantNames[i]))
220				}
221				if len(category.Extensions) == 0 {
222					t.Errorf("category[%d] %q has no default extensions", i, category.NameKey)
223				}
224			}
