200	func TestDownloaderStoreConfig_InitSeedsBuiltInCategories(t *testing.T) {
201		t.Run("fresh config with a download dir gets the built-in categories", func(t *testing.T) {
202			dir := t.TempDir()
203			cfg := &DownloaderStoreConfig{DownloadDir: dir}
204			cfg.Init()
205	
206			wantKeys := []string{"categoryMusic", "categoryVideo", "categoryDocument", "categoryProgram"}
207			wantNames := []string{"Music", "Video", "Document", "Program"}
208			if len(cfg.Categories) != len(wantKeys) {
209				t.Fatalf("categories = %d, want %d", len(cfg.Categories), len(wantKeys))
210			}
211			for i, category := range cfg.Categories {
212				if category.NameKey != wantKeys[i] {
213					t.Errorf("category[%d].NameKey = %q, want %q", i, category.NameKey, wantKeys[i])
214				}
215				if !category.IsBuiltIn {
216					t.Errorf("category[%d] %q is not built-in", i, category.NameKey)
217				}
218				if category.Path != filepath.Join(dir, wantNames[i]) {
219					t.Errorf("category[%d].Path = %q, want %q", i, category.Path, filepath.Join(dir, wantNames[i]))
220				}
221				if len(category.Extensions) == 0 {
222					t.Errorf("category[%d] %q has no default extensions", i, category.NameKey)
223				}
224			}
225		})
226	
227		// Init itself never reads the legacy key: Setup calls
228		// MigrateLegacyExtraCategories first, and only a config that skipped the
229		// migration ends up with the built-in seed.
230		t.Run("legacy extra downloadCategories is not read by Init alone", func(t *testing.T) {
231			cfg := &DownloaderStoreConfig{
232				DownloadDir: t.TempDir(),
233				Extra: map[string]any{
234					"downloadCategories": []any{map[string]any{"name": "Music", "path": "/old/Music"}},
235				},
236			}
237			cfg.Init()
238			if len(cfg.Categories) != 4 {
239				t.Fatalf("categories = %d, want the 4 built-ins seeded anyway", len(cfg.Categories))
240			}
241		})
242	
243		t.Run("existing categories and missing download dirs are untouched", func(t *testing.T) {
244			existing := []*DownloadCategory{{Name: "Mine", Path: "/downloads/Mine"}}
245			cfg := &DownloaderStoreConfig{DownloadDir: t.TempDir(), Categories: existing}
246			cfg.Init()
247			if len(cfg.Categories) != 1 || cfg.Categories[0].Name != "Mine" {
248				t.Fatalf("categories = %v, want the existing one", cfg.Categories)
249			}
250	
251			empty := &DownloaderStoreConfig{}
252			empty.Init()
253			if len(empty.Categories) != 0 {
254				t.Fatalf("categories = %d, want 0 without a download dir", len(empty.Categories))
255			}
256		})
257	}
