272	func TestDownloaderStoreConfig_MigrateLegacyExtraCategories(t *testing.T) {
273		t.Run("legacy built-ins move to the top level with their default extensions", func(t *testing.T) {
274			cfg := &DownloaderStoreConfig{
275				DownloadDir: "/downloads",
276				Extra: map[string]any{
277					"downloadCategories": []any{
278						map[string]any{"name": "", "path": "/old/Music", "isBuiltIn": true, "nameKey": "categoryMusic"},
279						map[string]any{"name": "Games", "path": "/old/Games"},
280					},
281					"themeMode": "dark",
282				},
283			}
284			if !cfg.MigrateLegacyExtraCategories() {
285				t.Fatal("migration reported no change")
286			}
287			if len(cfg.Categories) != 2 {
288				t.Fatalf("categories = %d, want the 2 legacy entries", len(cfg.Categories))
289			}
290			builtIn := cfg.Categories[0]
291			if builtIn.NameKey != "categoryMusic" || !builtIn.IsBuiltIn || builtIn.Path != "/old/Music" {
292				t.Fatalf("built-in category = %+v, want the legacy entry", builtIn)
293			}
294			if len(builtIn.Extensions) == 0 {
295				t.Fatal("migrated built-in must regain its default extensions")
296			}
297			custom := cfg.Categories[1]
298			if custom.Name != "Games" || custom.Path != "/old/Games" || len(custom.Extensions) != 0 {
299				t.Fatalf("custom category = %+v, want the legacy folder untouched", custom)
300			}
301			if _, ok := cfg.Extra["downloadCategories"]; ok {
302				t.Fatal("legacy key must be cleared")
303			}
304			if cfg.Extra["themeMode"] != "dark" {
305				t.Fatalf("unrelated extra entries must survive, got %v", cfg.Extra)
306			}
307	
308			// Setup runs Init after the migration, which must not seed over it.
309			cfg.Init()
310			if len(cfg.Categories) != 2 {
311				t.Fatalf("categories after Init = %d, want the migrated list kept", len(cfg.Categories))
312			}
313		})
314	
315		t.Run("existing top level categories are left alone", func(t *testing.T) {
316			cfg := &DownloaderStoreConfig{
317				Extra: map[string]any{
318					"downloadCategories": []any{map[string]any{"name": "Old", "path": "/old/Default"}},
319				},
320				Categories: []*DownloadCategory{{Name: "Mine", Path: "/downloads/Mine"}},
321			}
322			if cfg.MigrateLegacyExtraCategories() {
323				t.Fatal("migration must not overwrite existing categories")
324			}
325			if len(cfg.Categories) != 1 || cfg.Categories[0].Name != "Mine" {
326				t.Fatalf("categories = %v, want the existing one", cfg.Categories)
327			}
328			if _, ok := cfg.Extra["downloadCategories"]; !ok {
329				t.Fatal("legacy key must stay for a manual move")
330			}
331		})
332	
333		t.Run("missing, empty and malformed legacy lists are a no-op", func(t *testing.T) {
334			if (&DownloaderStoreConfig{}).MigrateLegacyExtraCategories() {
335				t.Fatal("empty config reported a change")
336			}
337			unrelated := &DownloaderStoreConfig{
338				Extra: map[string]any{"themeMode": "dark"},
339			}
340			if unrelated.MigrateLegacyExtraCategories() {
341				t.Fatal("config without the legacy key reported a change")
342			}
343			empty := &DownloaderStoreConfig{
344				Extra: map[string]any{"downloadCategories": []any{}},
345			}
346			if empty.MigrateLegacyExtraCategories() {
347				t.Fatal("empty legacy list reported a change")
348			}
349			malformed := &DownloaderStoreConfig{
350				Extra: map[string]any{"downloadCategories": "not-a-list"},
351			}
352			if malformed.MigrateLegacyExtraCategories() {
353				t.Fatal("malformed legacy list reported a change")
354			}
355			if _, ok := malformed.Extra["downloadCategories"]; !ok {
356				t.Fatal("malformed legacy key must stay untouched")
357			}
358		})
359	
360		t.Run("a nil entry in the legacy list is skipped", func(t *testing.T) {
361			cfg := &DownloaderStoreConfig{
362				DownloadDir: "/downloads",
363				Extra: map[string]any{
364					"downloadCategories": []any{
365						nil,
366						map[string]any{"name": "Games", "path": "/old/Games"},
367					},
368				},
369			}
370			if !cfg.MigrateLegacyExtraCategories() {
371				t.Fatal("migration reported no change")
372			}
373			if len(cfg.Categories) != 1 || cfg.Categories[0].Name != "Games" {
374				t.Fatalf("categories = %+v, want the single valid legacy entry", cfg.Categories)
375			}
376		})
377	}
